('APX-S-4934-1', 'APX-C-4934', 1, null, null, null, null, 1, 307, 'Subject: a beautiful tall Japanese fashion model in a bold cobalt blue and canary yellow power suit with wide-leg palazzo trousers and platform heels.', null, null, null, null, null, null),
('APX-S-4934-2', 'APX-C-4934', 2, null, null, null, 'One continuous shot, no cuts. She begins backstage — assistants making final adjustments — then steps through a white curtain into full outdoor sunlight for her first commanding full-body reveal on a bright white runway. She drives forward in a powerful stride, palazzo trousers billowing, cutting a smoldering glance toward the seated editors.', null, null, 'She begins backstage — assistants making final adjustments — then steps through a white curtain into full outdoor sunlight for her first commanding full-body reveal on a bright white runway.', null, 'driving', null, null, null, null),
